@startuml

class User {
  + id : int
  + name : string
  + address : string
  + birthday : date
}

class BusinessOwner {
  + linkedinAccount : string
  + pizzaRestaurants : PizzaRestaurant[]
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : time
  + pizzas : Pizza[]
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + id : int
  + dateAndTime : datetime
  + latestDeliveryTime : datetime
  + numberOfPeople : int
  + pizzas : Pizza[]
}

class EntertainmentOrder extends Order {
  + entertainmentType : string
  + duration : time
}

class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Minutes : double
  + availableDays : Day[]
  + pizzaRestaurants : PizzaRestaurant[]
}

class Day {
  + name : string
}

User "1" -- "0..*" BusinessOwner : is
BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
User "1" -- "*" Order : makes
Order "1" -- "*" Pizza : contains
Order "0..1" -- "*" EntertainmentOrder : is
Entertainer "1" -- "*" EntertainmentOrder : fulfills
Entertainer "1" -- "*" PizzaRestaurant : worksWith

@enduml

